def should_retry(success, transient, attempts):
    if success or not transient:
        return False
    return attempts in (0, 1, 2)

def may_launch(active_lease, uncertain_reservation, hash_match, authorized):
    if active_lease or uncertain_reservation:
        return False
    return bool(authorized and hash_match)

def may_promote(independent_pass, heldout_pass, donor_deleted, contaminated):
    if contaminated:
        return False
    return all((independent_pass, heldout_pass, donor_deleted))

def admit_source(authoritative, direct, stale, conflict):
    if stale or conflict:
        return False
    return bool(authoritative and direct)
